"""Business-only settings page (credentials live in Authorization Center)."""


def settings_html() -> str:
    return r'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>业务设置 · 115娱乐中心</title><style>
:root{--line:#174c54;--gold:#d3b370;--cyan:#16b9d1;--text:#e7ddc7;--muted:#978b73}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 72% 3%,#2a2013 0,#090805 40%,#050504 100%);color:var(--text);font:14px system-ui,-apple-system,"Microsoft YaHei",sans-serif}.shell{display:grid;grid-template-columns:235px 1fr;min-height:100vh}.side{background:#090805ef;border-right:1px solid var(--line);padding:18px 10px}.logo{font-size:21px;font-weight:800;color:var(--gold);padding:7px 12px 28px}.group{font-size:11px;color:#776c58;margin:14px 10px 7px;border-bottom:1px solid #3e341f;padding-bottom:8px}.nav{display:block;color:#c0ae89;text-decoration:none;padding:13px 16px;margin:3px 0;border-radius:12px;font-weight:700}.nav:hover,.nav.active{background:#113a40;color:#39d4e9}.top{height:64px;display:flex;align-items:center;padding:0 28px;border-bottom:1px solid var(--line);background:#080705ed}.heading{font-size:22px;font-weight:800;color:#35c7dd}.save{margin-left:auto;border:1px solid #23818c;background:#123940;color:#57dcea;border-radius:9px;padding:10px 19px}.wrap{max-width:1200px;margin:auto;padding:25px}.card{background:#12100b;border:1px solid var(--line);border-radius:15px;padding:22px;margin-bottom:18px}.card h2{color:#d8bd7e;margin-top:0}.hint{color:var(--muted);margin-bottom:18px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.field label{display:block;color:#a99c84;margin:0 0 7px}.field input,.field select{width:100%;height:44px;background:#090806;border:1px solid #245c64;border-radius:9px;color:#ddd;padding:0 12px}.dirrow{display:flex;gap:8px}.dirrow input{flex:1}.dirrow button{flex:none;width:46px;border:1px solid #77572b;background:#291d0e;color:#eecb82;border-radius:9px;cursor:pointer;font-size:18px}.switch{display:flex;align-items:center;gap:10px;padding-top:27px}.test{border:1px solid #77572b;background:#291d0e;color:#eecb82;border-radius:9px;padding:10px 15px}.toast{position:fixed;right:25px;bottom:25px;padding:13px 17px;border:1px solid #45b981;background:#153b31;color:#bff5d5;border-radius:10px;display:none}.toast.bad{background:#3b1e20;border-color:#b44b54;color:#ffd0d3}.modal{position:fixed;inset:0;background:#000b;display:none;place-items:center;z-index:50}.modal.open{display:grid}.dialog{width:min(680px,94vw);max-height:84vh;overflow:auto;background:#15120c;border:1px solid #23717c;border-radius:16px;padding:20px}.close{float:right;background:none;border:0;color:#ddd;font-size:25px}.crumb{color:#d8bd7e;margin:10px 0;word-break:break-all}.fdir{display:flex;justify-content:space-between;align-items:center;border:1px solid #2c3d3d;background:#0f0e0a;border-radius:10px;padding:11px 14px;margin:7px 0;color:#d5c7a8;cursor:pointer}.fdir:hover{border-color:#17a9bc;background:#14373d}.fdir button{border:1px solid #23818c;background:#123940;color:#57dcea;border-radius:8px;padding:7px 13px}.mtool{display:flex;gap:9px;margin-top:14px}.mtool button{border:1px solid #5f4827;background:#241a0e;color:#d8bb7d;border-radius:9px;padding:9px 14px}.mtool button.primary{border-color:#23818c;background:#123940;color:#57dcea}.fstate{color:#e8727b;padding:16px;text-align:center}.fstate button{border:1px solid #5f4827;background:#241a0e;color:#d8bb7d;border-radius:9px;padding:8px 14px;margin-top:10px}@media(max-width:800px){.shell{display:block}.side{display:none}.grid{grid-template-columns:1fr}.wrap{padding:13px}}
</style></head><body><div class="shell"><aside class="side"><div class="logo">◉ 影舟 MovieArk</div><div class="group">发现</div><a class="nav" href="/rankings">🏆 榜单</a><a class="nav" href="/explore">◉ 汇影</a><a class="nav" href="/search">⌕ 搜索</a><div class="group">订阅</div><a class="nav" href="/subscriptions">☷ 订阅列表</a><a class="nav" href="/tasks">▣ 订阅任务</a><a class="nav" href="/unlocks">◴ 解锁记录</a><div class="group">系统</div><a class="nav" href="/authorizations">🔑 授权中心</a><a class="nav active" href="/settings">⚙ 业务设置</a><a class="nav" href="/telegram">✈ Telegram</a><a class="nav" href="/logs">▤ 日志中心</a></aside><main><header class="top"><div class="heading">⚙ 业务设置</div><button class="save" id="save">保存设置</button></header><section class="wrap"><article class="card"><h2>115 保存相关</h2><div class="hint">这些目录和策略直接用于“搜索资源 → 转存到115”。账号和 Cookie 请到授权中心管理；保存目录请使用 📁 真实选择 115 网盘文件夹。</div><div class="grid"><div class="field"><label>115 保存目录</label><div class="dirrow"><input id="save_directory" placeholder="点击 📁 选择115网盘目录" readonly><button id="pick" title="选择115网盘目录">📁</button></div><input id="save_folder_id" type="hidden"></div><div class="field"><label>保存等待时间（秒）</label><input id="save_wait_seconds" type="number" min="0" max="3600"></div><div class="field"><label>重试次数</label><input id="retry_count" type="number" min="0" max="20"></div><div class="field"><label>重复资源处理</label><select id="duplicate_policy"><option value="skip">跳过</option><option value="rename">自动重命名</option><option value="overwrite">覆盖记录（不主动删除文件）</option></select></div><label class="switch"><input id="subscription_auto_transfer" type="checkbox"> 订阅命中资源后自动解锁并转存</label><div class="field"><label>订阅检查周期（秒）</label><input id="subscription_interval" type="number" min="300" max="86400"></div></div></article><article class="card"><h2>ED2K 下载 / 保存</h2><div class="hint">通过115云下载处理 ED2K 和磁力任务。</div><div class="grid"><label class="switch"><input id="offline_enabled" type="checkbox"> 启用 ED2K / 磁力云下载</label><div class="field"><label>115 云下载保存目录</label><input id="ed2k_directory"></div><div class="field"><label>轮询间隔（秒）</label><input id="ed2k_poll_interval" type="number" min="10" max="3600"></div><div class="field"><label>重试次数</label><input id="ed2k_retry_count" type="number" min="0" max="20"></div><label class="switch"><input id="ed2k_auto_archive" type="checkbox"> 下载完成后自动归档/整理</label><div><button class="test" id="test">测试 ED2K 配置</button></div></div></article></section></main></div><div id="modal" class="modal"><div class="dialog"><button id="close" class="close">×</button><h2>选择 115 保存目录</h2><p class="crumb" id="crumb">根目录</p><div id="folders"><div class="fstate">正在读取115目录…</div></div><div class="mtool"><button id="up">⬆ 返回上一级</button><button class="primary" id="choose">选择当前目录</button></div></div></div><div id="toast" class="toast"></div><script>
const ids=['save_directory','save_folder_id','save_wait_seconds','retry_count','duplicate_policy','subscription_auto_transfer','subscription_interval','offline_enabled','ed2k_directory','ed2k_poll_interval','ed2k_retry_count','ed2k_auto_archive'],$=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const F={cid:'0',path:[]};async function load(){const d=await fetch('/api/web/settings/business').then(r=>r.json());ids.forEach(id=>{const e=$('#'+id);if(e.type==='checkbox')e.checked=!!d[id];else e.value=d[id]??''})}async function save(){const body={root_directory:'',scrape_directory:'',save_directory:$('#save_directory').value.trim(),save_folder_id:$('#save_folder_id').value.trim(),save_wait_seconds:+$('#save_wait_seconds').value,retry_count:+$('#retry_count').value,duplicate_policy:$('#duplicate_policy').value,subscription_auto_transfer:$('#subscription_auto_transfer').checked,subscription_interval:+$('#subscription_interval').value,offline_enabled:$('#offline_enabled').checked,ed2k_directory:$('#ed2k_directory').value.trim(),ed2k_poll_interval:+$('#ed2k_poll_interval').value,ed2k_retry_count:+$('#ed2k_retry_count').value,ed2k_auto_archive:$('#ed2k_auto_archive').checked};const r=await fetch('/api/web/settings/business',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),d=await r.json();toast(r.ok?'设置已保存':d.detail||'保存失败',!r.ok)}async function test(){const r=await fetch('/api/web/settings/ed2k-test',{method:'POST'}),d=await r.json();toast(d.message||d.detail||'测试完成',!r.ok)}async function openPicker(){F.cid='0';F.path=[];$('#modal').classList.add('open');await fetchFolders()}async function fetchFolders(){const box=$('#folders');box.innerHTML='<div class="fstate">正在读取115目录…</div>';try{const r=await fetch('/api/web/115/folders?cid='+encodeURIComponent(F.cid)),d=await r.json();if(r.status===401)throw new PickError('115 授权已失效，请重新扫码。','auth');if(!r.ok)throw new PickError(d.detail||'读取目录失败','retry');F.path=d.path||F.path;$('#crumb').textContent=(d.path||[]).map(p=>p.name).join(' / ')||'根目录';if(!d.folders.length){box.innerHTML='<div class="fstate">当前目录下没有子文件夹，可直接选择当前目录。</div>';return}box.innerHTML=d.folders.map(f=>`<div class="fdir" data-cid="${esc(f.cid)}"><span>📁 ${esc(f.name)}</span><button>进入</button></div>`).join('');document.querySelectorAll('.fdir').forEach(el=>el.onclick=e=>{if(e.target.tagName==='BUTTON'){F.cid=el.dataset.cid;F.path=[...(d.path||[]),{cid:el.dataset.cid,name:el.querySelector('span').textContent.replace('📁 ','')}];fetchFolders()}})}catch(e){if(e instanceof PickError&&e.kind==='auth')box.innerHTML=`<div class="fstate">115 授权已失效，请重新扫码。<br><button onclick="closePicker()">知道了</button></div>`;else box.innerHTML=`<div class="fstate">加载目录失败：${esc(e.message)}<br><button onclick="fetchFolders()">重试</button></div>`}}function PickError(m,k){this.message=m;this.kind=k}function choose(){if(!F.cid)return toast('请先进入一个目录',true);const pathName=(F.path||[]).map(p=>p.name).join('/')||'根目录';$('#save_directory').value=pathName;$('#save_folder_id').value=F.cid;toast('已选择目录：'+pathName);$('#modal').classList.remove('open')}function up(){if(!F.path.length)return toast('已经在根目录',true);F.path.pop();F.cid=F.path.length?F.path[F.path.length-1].cid:'0';fetchFolders()}function closePicker(){$('#modal').classList.remove('open')}function toast(m,b=false){const t=$('#toast');t.textContent=m;t.className='toast'+(b?' bad':'');t.style.display='block';setTimeout(()=>t.style.display='none',3200)}$('#save').onclick=save;$('#test').onclick=test;$('#pick').onclick=openPicker;$('#choose').onclick=choose;$('#up').onclick=up;$('#close').onclick=closePicker;load();
</script></body></html>'''
